const normalized = $('Extract Azimuth').first().json;
const rules = $input.all().map(i => i.json);

const az = Number(normalized.azimuth);

function map(value, inMin, inMax, outMin, outMax) {
  outMin = Number(outMin ?? 0);
  outMax = Number(outMax ?? outMin);

  if (inMin === inMax) return outMin;

  return outMin + ((value - inMin) * (outMax - outMin)) / (inMax - inMin);
}

let feedback = {
  ...normalized,
  alertGiven: 'no',
  pulses: 0,
  intensity: 0,
  duration: 0,
  interval: 0,
  fbRangeID: 0,
  reason: 'time_interval'
};

for (const r of rules) {
  const minV = Number(r.minvalue);
  const maxV = Number(r.maxvalue);

  if (!Number.isFinite(minV) || !Number.isFinite(maxV)) continue;

  if (az >= minV && az <= maxV) {
    feedback.pulses = Math.round(map(az, minV, maxV, r.minpulses, r.maxpulses));
    feedback.intensity = Math.round(map(az, minV, maxV, r.minintensity, r.maxintensity));
    feedback.duration = Math.round(map(az, minV, maxV, r.minduration, r.maxduration));
    feedback.interval = Math.round(map(az, minV, maxV, r.mininterval, r.maxinterval));

    feedback.fbRangeID = Number(r.id ?? 0);
    feedback.alertGiven = feedback.pulses > 0 ? 'yes' : 'no';
    break;
  }
}

return [{ json: feedback }];

const p = $json;

if (!p.userID || !p.watchID || !p.phoneID) {
  return [{
    json: {
      statusCode: 400,
      error: 'Missing identifiers',
      payload: p
    }
  }];
}

return [{
