    .reduce((current, key) => current?.[key], obj);
}

let value = null;
let usedPath = null;

for (const path of config.paths) {
  const candidate = getByPath(api, path);

  if (candidate != null && candidate !== '') {
    value = candidate;
    usedPath = path;
    break;
  }
}

if (value == null) {
  return [{
    json: {
      ...normalized,
      statusCode: 500,
      error: `${config.valueName} value missing in API response`,
      triedPaths: config.paths,
      rawApi: api
    }
  }];
}

const numericValue = Number(value);

if (Number.isNaN(numericValue)) {
  return [{
    json: {
      ...normalized,
      statusCode: 500,
      error: `${config.valueName} value is not numeric`,
      got: value,
      usedPath,
      rawApi: api
    }
  }];
}

return [{
  json: {
    ...normalized,
    value: numericValue,
    valueName: config.valueName,
    extractedFrom: usedPath
  }
}];

/**
 * Construct API Request
 *
 * Purpose:
 * Normalized request data â†’ build external API URL â†’ pass URL to HTTP Request node
 *
 * Usually you only change the CONFIG section.
 *
 * Output:
 * {
 *   ...previousData,
 *   url: "https://external-api.com/...",
 *   requestMeta: { ... }
 * }
 */


// ======================================================
// CONFIG â€” CHANGE THIS SECTION
// ======================================================

const API_NAME = "UV Index Monitoring";

const API_REQUIRES_KEY = false;

const API_KEY = "";

const BASE_URL = "https://api.open-meteo.com/v1/forecast";

const REQUIRED_FIELDS = ["lat", "lon"];

function buildUrl({ lat, lon, body, type, apiKey }) {
  const params = [
    `current=uv_index`,
    `latitude=${encodeURIComponent(lat)}`,
    `longitude=${encodeURIComponent(lon)}`
  ];

  return `${BASE_URL}?${params.join("&")}`;
}


// ======================================================
// DO NOT CHANGE BELOW
// ======================================================

const prev = $input.first().json;
const body = prev.body ?? {};

const type = prev.type ?? body.type ?? body.sensorType ?? "UnknownType";

/**
 * Reads a value from:
 * 1. normalized top-level data, for example prev.lat
 * 2. original body, for example body.lat
 *
 * This makes the node flexible.
 */
function getField(fieldName) {
  return prev[fieldName] ?? body[fieldName] ?? null;
}


// ------------------------------------------------------
// Validate required fields
// ------------------------------------------------------

const missingFields = [];

for (const field of REQUIRED_FIELDS) {
  const value = getField(field);

  if (value == null || value === "") {
    missingFields.push(field);
  }
}

if (missingFields.length > 0) {
  return [{
    json: {
      ...prev,
      statusCode: 400,
      error: "Missing required fields",
      missingFields,
      got: Object.fromEntries(
        REQUIRED_FIELDS.map(field => [field, getField(field)])
      )
    }
  }];
}


// ------------------------------------------------------
// Validate API key only if needed
// ------------------------------------------------------

if (
  API_REQUIRES_KEY &&
  (!API_KEY || API_KEY === "PUT_API_KEY_HERE")
) {
  return [{
    json: {
      ...prev,
      statusCode: 500,
      error: `${API_NAME} API key is not configured`,
      hint: "Set API_KEY in the CONFIG section, or set API_REQUIRES_KEY to false if this API does not need a key."
    }
  }];
}


// ------------------------------------------------------
// Read common fields
// ------------------------------------------------------

const latRaw = getField("lat");
const lonRaw = getField("lon") ?? getField("long");

const lat = latRaw == null ? null : Number(latRaw);
const lon = lonRaw == null ? null : Number(lonRaw);


// ------------------------------------------------------
// Validate lat/lon only if this API requires them
// ------------------------------------------------------

if (REQUIRED_FIELDS.includes("lat") && Number.isNaN(lat)) {
  return [{
    json: {
      ...prev,
      statusCode: 400,
      error: "Invalid lat value",
      got: latRaw
    }
  }];
}

if (REQUIRED_FIELDS.includes("lon") && Number.isNaN(lon)) {
  return [{
    json: {
      ...prev,
      statusCode: 400,
      error: "Invalid lon value",
      got: lonRaw
    }
  }];
}


// ------------------------------------------------------
// Build URL
// ------------------------------------------------------

let url;

try {
  url = buildUrl({
    type,
    lat,
    lon,
    body,
    apiKey: API_KEY
  });
} catch (error) {
  return [{
    json: {
      ...prev,
      statusCode: 500,
      error: "Failed to build API URL",
      message: error.message
    }
  }];
}

if (!url) {
  return [{
    json: {
      ...prev,
      statusCode: 500,
      error: "buildUrl did not return a URL"
    }
  }];
}


// ------------------------------------------------------
// Return data for HTTP Request node
// ------------------------------------------------------

return [{
  json: {
    ...prev,

    // The next HTTP Request node should use:
    // URL: {{ $json.url }}
    url,

    // Keep useful normalized values for later nodes
    type,
    lat,
    lon,

    requestMeta: {
      apiName: API_NAME,
      type,
      requiredFields: REQUIRED_FIELDS,
      apiRequiresKey: API_REQUIRES_KEY
    }
  }
}];

//normalize the inputs params

const body = $json.body ?? {};

if (body.userId == null) throw new Error('Missing UserID');
if (body.smartWatchId == null) throw new Error('Missing SmartWatchID');
if (body.androidId == null) throw new Error('Missing AndroidID');
if (!$json.type) throw new Error('Missing type (should come from Set node)');

return [{
