      intensity: p.intensity,
      duration: p.duration,
      interval: p.interval,
      fbRangeID: p.fbRangeID,
      reason: p.reason
    }
  }
}];

const measurement =
  $('Calculate SocialMediaHostility Value').first().json;

const rules = $input.all().map(item => item.json);
const value = Number(measurement.value);

const interpolate = (
  input,
  inputMin,
  inputMax,
  outputMin,
  outputMax
) => {
  if (inputMin === inputMax) return outputMin;

  return outputMin +
    ((input - inputMin) * (outputMax - outputMin)) /
    (inputMax - inputMin);
};

let matchingRule = null;

for (const rule of rules) {
  const minValue = Number(rule.minvalue);
  const maxValue = Number(rule.maxvalue);

  if (
    Number.isFinite(minValue) &&
    Number.isFinite(maxValue) &&
    value >= minValue &&
    value <= maxValue
  ) {
    matchingRule = rule;
    break;
  }
}

if (!matchingRule) {
  return [{
    json: {
      ...measurement,
      ok: false,
      error: 'no_active_mapping'
    }
  }];
}

const minValue = Number(matchingRule.minvalue);
const maxValue = Number(matchingRule.maxvalue);

const mapField = field =>
  interpolate(
    value,
    minValue,
    maxValue,
    Number(matchingRule[`min${field}`]),
    Number(matchingRule[`max${field}`])
  );

const pulses =
  Math.max(1, Math.round(mapField('pulses')));

const intensity =
  Math.min(
    255,
    Math.max(1, Math.round(mapField('intensity')))
  );

const duration =
  Math.max(0, Math.round(mapField('duration')));

const interval =
  Math.max(0, Math.round(mapField('interval')));

return [{
  json: {
    ...measurement,
    ok: true,
    alertGiven: 'yes',
    pulses,
    intensity,
    duration,
    interval,
    fbRangeID: Number(matchingRule.id),
    reason: 'time_interval'
  }
}];

