const input = $input.first()?.json ?? {};
const error = input.error;

const message =
  error?.description ??
  error?.message ??
  input.description ??
  input.message ??
  (typeof error === 'string' ? error : null) ??
  'social_media_hostility_measurement_failed';

return [{
  json: {
    type: 'SocialMediaHostility',
    status: 'error',
    alertGiven: 'no',
    pulses: 0,
    intensity: 0,
    duration: 0,
    interval: 0,
    reason: 'external_error',
    error: String(message).slice(0, 200)
  }
}];

const n = $('Normalize Generic UseCase Request').first().json;
const prepared =
  $('Prepare SocialMediaHostility Posts').first().json;

const results = $json.results;

if (
  !Array.isArray(results) ||
  results.length !== prepared.texts.length
) {
  return [{
    json: {
      ok: false,
      error: 'invalid_moderation_result_count'
    }
  }];
}

const categories = [
  'hate',
  'hate/threatening',
  'harassment',
  'harassment/threatening'
];

const scores = [];

for (const result of results) {
  const values = categories.map(category =>
    Number(result?.category_scores?.[category])
  );

  if (values.some(value => !Number.isFinite(value))) {
    return [{
      json: {
        ok: false,
        error: 'invalid_moderation_scores'
      }
    }];
  }

  scores.push(Math.max(...values));
}

scores.sort((a, b) => b - a);

const groups = [
  { values: scores.slice(0, 3), weight: 0.60 },
  { values: scores.slice(3, 10), weight: 0.25 },
  { values: scores.slice(10, 40), weight: 0.15 }
].filter(group => group.values.length > 0);

let weightedTotal = 0;
let activeWeight = 0;

for (const group of groups) {
  const mean =
    group.values.reduce((sum, value) => sum + value, 0) /
    group.values.length;

  weightedTotal += mean * group.weight;
  activeWeight += group.weight;
}

if (activeWeight === 0) {
  return [{
    json: {
      ok: false,
      error: 'no_moderation_scores'
    }
  }];
}

const rawScore = (weightedTotal / activeWeight) * 100;
const value = Math.round(
  Math.min(100, Math.max(0, rawScore)) * 10
) / 10;

return [{
  json: {
    ok: true,
    userID: n.userID,
    watchID: n.watchID,
    phoneID: n.phoneID,
    type: 'SocialMediaHostility',
    value,
    source: 'Bluesky',
    postCount: prepared.postCount,
    measuredAt: new Date().toISOString()
  }
}];

const firstItem = $input.first()?.json ?? {};
const response = firstItem.body ?? firstItem;
const feed = Array.isArray(response.feed)
  ? response.feed
  : [];

const seen = new Set();
const prepared = [];

for (const feedItem of feed) {
  const post = feedItem?.post;
  const record = post?.record;

  if (!post || !record) continue;

  // Skip reposts and replies.
  if (feedItem.reason?.$type === 'app.bsky.feed.defs#reasonRepost') {
    continue;
  }

  if (record.reply) continue;

  // Keep explicitly English-language posts only.
  if (
    !Array.isArray(record.langs) ||
    !record.langs.includes('en')
  ) {
    continue;
  }

  const id = String(post.uri ?? '').trim();

  const text = String(record.text ?? '')
    .replace(/\s+/g, ' ')
    .trim();

  if (!id || !text || seen.has(id)) continue;

  seen.add(id);
  prepared.push({ id, text });

  if (prepared.length === 40) break;
}

if (prepared.length < 10) {
  return [{
    json: {
      ok: false,
      error: 'insufficient_english_posts',
      postCount: prepared.length
    }
  }];
}

return [{
  json: {
    ok: true,
    texts: prepared.map(post => post.text),
    postIds: prepared.map(post => post.id),
    postCount: prepared.length
  }
}];

const lat = Number($json.body?.lat ?? $json.lat);
const lon = Number($json.body?.lon ?? $json.lon);

if (!Number.isFinite(lat) || lat < -90 || lat > 90) {
  throw new Error("TrafficSense requires a valid latitude");
}

if (!Number.isFinite(lon) || lon < -180 || lon > 180) {
  throw new Error("TrafficSense requires a valid longitude");
}

return [{
