}

const currentSpeed = Number(flow.currentSpeed);
const freeFlowSpeed = Number(flow.freeFlowSpeed);

if (
  !Number.isFinite(currentSpeed) ||
  !Number.isFinite(freeFlowSpeed) ||
  freeFlowSpeed <= 0
) {
  throw new Error("TomTom returned invalid speed values");
}

const rawScore = flow.roadClosure
  ? 100
  : 100 * (1 - currentSpeed / freeFlowSpeed);

const value = Math.round(
  Math.max(0, Math.min(100, rawScore)) * 10
) / 10;

return [{
  json: {
