const traffic = $("Calculate TrafficSense").first().json;
const rules = $input.all().map(item => item.json);
const value = Number(traffic.value);

if (!Number.isFinite(value)) {
  throw new Error("TrafficSense value is not numeric");
}

function interpolate(value, inMin, inMax, outMin, outMax) {
  const low = Number(outMin ?? 0);
  const high = Number(outMax ?? low);

  if (inMin === inMax) {
    return low;
  }

  return low +
    ((value - inMin) * (high - low)) /
    (inMax - inMin);
}

const feedback = {
  ...traffic,
  alertGiven: "no",
  pulses: 0,
  intensity: 0,
  duration: 0,
  interval: 0,
  fbRangeID: 0,
  reason: "time_interval"
};

for (const rule of rules) {
  const minValue = Number(rule.minvalue);
  const maxValue = Number(rule.maxvalue);

  if (!Number.isFinite(minValue) ||
      !Number.isFinite(maxValue)) {
    continue;
  }

  if (value >= minValue && value <= maxValue) {
    feedback.pulses = Math.round(
      interpolate(
        value,
        minValue,
        maxValue,
        rule.minpulses,
        rule.maxpulses
      )
    );

    feedback.intensity = Math.round(
      interpolate(
        value,
        minValue,
        maxValue,
        rule.minintensity,
        rule.maxintensity
      )
    );

    feedback.duration = Math.round(
      interpolate(
        value,
        minValue,
        maxValue,
        rule.minduration,
        rule.maxduration
      )
    );

    feedback.interval = Math.round(
      interpolate(
        value,
        minValue,
        maxValue,
        rule.mininterval,
        rule.maxinterval
      )
    );

    feedback.fbRangeID = Number(rule.id ?? 0);
    feedback.alertGiven =
      feedback.pulses > 0 ? "yes" : "no";

    break;
  }
}

return [{ json: feedback }];

const payload = $json;

if (!payload.userID ||
    !payload.watchID ||
