const watchID = Number(input.watchID);
const phoneID = Number(input.phoneID);
const value = Number(input.value);

if (![userID, watchID, phoneID].every(id => Number.isInteger(id) && id > 0)) {
  throw new Error('CountdownAwareness identifiers are missing or invalid');
}
if (!Number.isFinite(value) || value < 0) {
  throw new Error('CountdownAwareness remaining seconds must be a non-negative number');
}

return [{ json: { userID, watchID, phoneID, type: 'CountdownAwareness', value } }];

const measurement = $('Normalize CountdownAwareness').first().json;
const rules = $input.all().map(item => item.json);
const value = measurement.value;

const interpolate = (input, inputMin, inputMax, outputMin, outputMax) => {
  const low = Number(outputMin);
  const high = Number(outputMax);
  if (![low, high].every(Number.isFinite)) return 0;
  return inputMin === inputMax
    ? low
    : low + ((input - inputMin) * (high - low)) / (inputMax - inputMin);
};

const feedback = {
  ...measurement,
  alertGiven: 'no',
  pulses: 0,
  intensity: 0,
  duration: 0,
  interval: 0,
  fbRangeID: 9999,
  reason: 'no_matching_rule'
};

for (const rule of rules) {
  const minValue = Number(rule.minvalue);
  const maxValue = Number(rule.maxvalue);
  if (!Number.isFinite(minValue) || !Number.isFinite(maxValue) ||
      value < minValue || value > maxValue) continue;

  feedback.pulses = Math.max(0, Math.round(interpolate(value, minValue, maxValue, rule.minpulses, rule.maxpulses)));
  feedback.intensity = Math.max(0, Math.round(interpolate(value, minValue, maxValue, rule.minintensity, rule.maxintensity)));
  feedback.duration = Math.max(0, Math.round(interpolate(value, minValue, maxValue, rule.minduration, rule.maxduration)));
  feedback.interval = Math.max(0, Math.round(interpolate(value, minValue, maxValue, rule.mininterval, rule.maxinterval)));
  feedback.fbRangeID = Number(rule.id);
  feedback.alertGiven = feedback.pulses > 0 ? 'yes' : 'no';
  feedback.reason = 'time_interval';
  break;
}

return [{ json: feedback }];

